/**
 * Minimal isomorphic-git HTTP client: `node:https`, streamed, byte-counted.
 *
 * Why not `isomorphic-git/http/web`? It would use the runtime's global `fetch`
 * — our `host/fetch-shim.cjs` — which works, but it buffers the whole response
 * and reports progress in *object counts*, not bytes. Both matter here:
 *
 *   - the pack size has to be enforced before the memory is spent, because
 *     isomorphic-git holds the packfile and its deltas in RAM (measured RSS
 *     ≈ 100 MB + 11 × pack);
 *   - the tool tells the model how big the download was, in bytes.
 *
 * Owning the client also drops the dependency on the global fetch being the
 * shim, which makes the tool testable outside the runtime and removes a
 * failure mode (Node's undici dies on WebAssembly under `--jitless`).
 */

import http from "node:http";
import https from "node:https";
import tls from "node:tls";
import net from "node:net";
import { URL } from "node:url";

/** Write whatever body js-git handed us; it may be an array of chunks. */
function writeBody(request, body) {
	if (body === undefined || body === null) {
		request.end();
		return;
	}
	if (typeof body === "string" || Buffer.isBuffer(body) || body instanceof Uint8Array) {
		request.end(body);
		return;
	}
	if (Array.isArray(body)) {
		for (const chunk of body) {
			request.write(chunk);
		}
		request.end();
		return;
	}
	if (typeof body.pipe === "function") {
		body.pipe(request);
		return;
	}
	if (typeof body[Symbol.asyncIterator] === "function") {
		void (async () => {
			for await (const chunk of body) {
				request.write(chunk);
			}
			request.end();
		})();
		return;
	}
	request.end();
}

/**
 * Wrap the response body so every chunk is counted as it leaves the socket,
 * and the transfer is destroyed the moment it crosses `limitBytes`.
 *
 * Returns an async iterable of Buffers, which is the shape isomorphic-git
 * reads from an http plugin.
 */
async function* countedBody(response, state, limitBytes) {
	try {
		for await (const chunk of response) {
			state.bytes += chunk.length;
			if (state.bytes > limitBytes) {
				response.destroy();
				throw state.tooLarge();
			}
			yield chunk;
		}
	} finally {
		if (!response.destroyed) {
			response.destroy();
		}
	}
}

/**
 * Build an http plugin bound to one transfer's accounting.
 *
 * @param {object} options
 * @param {number} options.limitBytes  hard ceiling for the whole transfer
 * @param {number} options.timeoutMs   per-request socket timeout
 * @param {() => Error} options.tooLarge  factory for the "over the cap" error
 */
/**
 * Open a CONNECT tunnel through an HTTP proxy and return the raw socket.
 *
 * HarmonyOS exposes the user's system proxy as host:port (`getDefaultHttpProxy`)
 * but Node has no idea it exists, so ArkTS passes it down and we tunnel here.
 * Without this, a device behind a proxy simply cannot clone — and on a phone
 * there is no `git`, no `curl`, and no shell to work around it.
 */
function connectTunnel(proxy, target, timeoutMs) {
	return new Promise((resolve, reject) => {
		const port = target.port === undefined || target.port.length === 0
			? (target.protocol === "https:" ? 443 : 80)
			: Number(target.port);
		const authority = `${target.hostname}:${port}`;
		const request = http.request({
			host: proxy.host,
			port: proxy.port,
			method: "CONNECT",
			path: authority,
			headers: { host: authority },
			agent: false
		});
		request.setTimeout(timeoutMs, () => {
			request.destroy(new Error(`proxy ${proxy.host}:${proxy.port} timed out on CONNECT ${authority}`));
		});
		request.on("error", (error) => {
			reject(new Error(`proxy ${proxy.host}:${proxy.port} refused CONNECT ${authority}: ${error.message}`));
		});
		request.on("connect", (response, socket) => {
			if (response.statusCode !== 200) {
				socket.destroy();
				reject(new Error(
					`proxy ${proxy.host}:${proxy.port} answered CONNECT ${authority} with ${response.statusCode} ` +
					`${response.statusMessage === undefined ? "" : response.statusMessage}`
				));
				return;
			}
			resolve(socket);
		});
		request.end();
	});
}

/**
 * An https.Agent whose sockets come from a CONNECT tunnel.
 *
 * A request-level `createConnection` is ignored by Node: the hook lives on the
 * Agent, so passing it as an option silently does nothing and the request goes
 * direct. That failure mode is invisible when the direct route happens to work
 * — which is exactly how the first version of this "support" passed its own
 * test while the proxy saw zero CONNECTs. Hence a real Agent subclass.
 */
class ProxyTunnelAgent extends https.Agent {
	constructor(proxy, timeoutMs) {
		super({ keepAlive: false });
		this.proxy = proxy;
		this.timeoutMs = timeoutMs;
	}

	/**
	 * Agent hooks are synchronous: `createConnection` must hand back a socket
	 * immediately, so an async CONNECT cannot live there (returning a promise
	 * makes Node treat it as a stream and fail with `s.on is not a function`).
	 * `addRequest` may be async, so the tunnel is opened there and the finished
	 * socket is injected before the request is written.
	 */
	createConnection() {
		throw new Error("ProxyTunnelAgent opens its socket in addRequest");
	}

	async addRequest(request, options) {
		const target = {
			protocol: "https:",
			hostname: options.host === undefined ? options.hostname : options.host,
			port: String(options.port === undefined ? 443 : options.port)
		};
		try {
			const raw = await connectTunnel(this.proxy, target, this.timeoutMs);
			const socket = tls.connect({ socket: raw, servername: target.hostname });
			await new Promise((resolve, reject) => {
				socket.once("secureConnect", resolve);
				socket.once("error", reject);
			});
			request.onSocket(socket);
		} catch (error) {
			// Two traps here, both found the hard way:
			//  - a rejected promise from addRequest is an *unhandled rejection*,
			//    i.e. a crash on device, not an error message;
			//  - `request.destroy(error)` before any socket is attached does not
			//    emit "error" — the request just hangs forever (reproducible with
			//    a 3-line Agent), and isomorphic-git waits on it.
			// Attach a dead socket first so the error has somewhere to land.
			const dead = new net.Socket();
			request.onSocket(dead);
			request.destroy(error);
		}
	}
}

export function createHttpClient(options) {
	const state = { bytes: 0, tooLarge: options.tooLarge };
	const proxy = options.proxy === undefined || options.proxy === null ? undefined : options.proxy;
	return {
		/** Bytes that crossed the wire so far (the cap is enforced on this). */
		bytes: () => state.bytes,
		async request({ url, method = "GET", headers = {}, body }) {
			const target = new URL(url);
			const transport = target.protocol === "https:" ? https : http;
			const defaultPort = target.protocol === "https:" ? 443 : 80;
			const requestOptions = proxy === undefined
				? {
					protocol: target.protocol,
					hostname: target.hostname,
					port: target.port || defaultPort,
					path: `${target.pathname}${target.search}`,
					method,
					headers
				}
				: {
					protocol: target.protocol,
					hostname: target.hostname,
					port: target.port || defaultPort,
					path: `${target.pathname}${target.search}`,
					method,
					headers,
					// HTTPS through a proxy is tunnelled: TLS is negotiated end to end,
					// so the proxy only sees CONNECT and ciphertext, never the path.
					...(target.protocol === "https:"
						? { agent: new ProxyTunnelAgent(proxy, options.timeoutMs) }
						: { host: proxy.host, port: proxy.port, path: url })
				};
			const response = await new Promise((resolve, reject) => {
				const request = transport.request(requestOptions, resolve);
				request.setTimeout(options.timeoutMs, () => {
					request.destroy(new Error(`request to ${target.host} timed out`));
				});
				request.on("error", reject);
				writeBody(request, body);
			});
			return {
				url,
				method,
				headers: response.headers,
				body: countedBody(response, state, options.limitBytes),
				statusCode: response.statusCode,
				statusMessage: response.statusMessage
			};
		}
	};
}

/**
 * Read the proxy from the environment, if ArkTS handed one down.
 *
 * Only http(s) proxies are understood: a SOCKS proxy would need a different
 * handshake, and silently ignoring it is worse than reporting the truth.
 */
export function proxyFromEnv(env) {
	const raw = env === undefined ? undefined : env.DSH_HTTPS_PROXY;
	const value = typeof raw === "string" ? raw.trim() : "";
	if (value.length === 0) {
		return { proxy: undefined, note: "direct" };
	}
	let parsed;
	try {
		parsed = new URL(value);
	} catch (error) {
		return { proxy: undefined, note: `ignored DSH_HTTPS_PROXY (not a URL): ${value}` };
	}
	if (parsed.protocol !== "http:") {
		return { proxy: undefined, note: `ignored DSH_HTTPS_PROXY (only http: is tunnelled): ${value}` };
	}
	return {
		proxy: { host: parsed.hostname, port: Number(parsed.port.length === 0 ? "80" : parsed.port) },
		note: `proxy ${parsed.hostname}:${parsed.port.length === 0 ? "80" : parsed.port}`
	};
}
